export interface ConnectorConfig {
  /** Secret used by Intercom to sign webhooks (X-Hub-Signature). Provided via INTERCOM_WEBHOOK_SECRET env var. */
  intercomWebhookSecret: string
  /** Zendesk API token (Bearer). Provided via ZENDESK_API_TOKEN env var. */
  zendeskApiToken: string
  /** Zendesk subdomain (e.g. "mycompany" for mycompany.zendesk.com). Provided via ZENDESK_SUBDOMAIN env var. */
  zendeskSubdomain: string
  /** Injected fetch for testing; defaults to global fetch. */
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  type: string
  topic: string
  id: string
  app_id: string
  created_at: number
  delivery_attempts: number
  first_sent_at: number
  data: {
    item: {
      type: string
      id: string
      conversation_message: {
        url: string
      }
      tags: {
        type: string
        tags: Array<{
          id: string
          name: string
        }>
      }
    }
  }
}

export interface HandleResult {
  ticketId: number
  ticketUrl: string
}

export async function handle(payload: IntercomWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required fields
  if (!payload.data?.item?.conversation_message?.url) {
    throw new Error('Missing required field: data.item.conversation_message.url')
  }
  if (!payload.data?.item?.id) {
    throw new Error('Missing required field: data.item.id')
  }
  if (!payload.data?.item?.tags?.tags) {
    throw new Error('Missing required field: data.item.tags.tags')
  }

  // Verify the conversation has the "refund" tag
  const hasRefundTag = payload.data.item.tags.tags.some((tag) => tag.name === 'refund')
  if (!hasRefundTag) {
    throw new Error('Conversation does not have the "refund" tag')
  }

  const conversationUrl = payload.data.item.conversation_message.url
  const conversationId = payload.data.item.id

  // Build Zendesk ticket request
  const commentBody = `Conversation URL: ${conversationUrl}\nConversation ID: ${conversationId}`
  const requestBody = {
    ticket: {
      comment: {
        body: commentBody
      }
    }
  }

  const fetchFn = config.fetch ?? fetch
  const url = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskApiToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  })

  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = (await response.json()) as { ticket: { id: number; url: string } }
  // Replace {subdomain} placeholder in the returned URL with the actual subdomain
  const ticketUrl = result.ticket.url.replace('{subdomain}', config.zendeskSubdomain)
  return {
    ticketId: result.ticket.id,
    ticketUrl
  }
}

